// SPDX-License-Identifier: AGPL-3.0-or-later
pragma solidity 0.7.5;

import {AccessControl} from "@openzeppelin/contracts/access/AccessControl.sol";

interface IERC20 {
    function totalSupply() external view returns (uint256);
    function balanceOf(address account) external view returns (uint256);
    function transfer(address recipient, uint256 amount) external returns (bool);
    function allowance(address owner, address spender) external view returns (uint256);
    function approve(address spender, uint256 amount) external returns (bool);
    function transferFrom(address sender, address recipient, uint256 amount) external returns (bool);

    event Transfer(address indexed from, address indexed to, uint256 value);
    event Approval(address indexed owner, address indexed spender, uint256 value);
}

library SafeMath {
    function add(uint256 a, uint256 b) internal pure returns (uint256) {
        uint256 c = a + b;
        require(c >= a, "SafeMath: addition overflow");
        return c;
    }

    function sub(uint256 a, uint256 b) internal pure returns (uint256) {
        return sub(a, b, "SafeMath: subtraction overflow");
    }

    function sub(uint256 a, uint256 b, string memory errorMessage) internal pure returns (uint256) {
        require(b <= a, errorMessage);
        uint256 c = a - b;
        return c;
    }

    function mul(uint256 a, uint256 b) internal pure returns (uint256) {
        if (a == 0) {
            return 0;
        }
        uint256 c = a * b;
        require(c / a == b, "SafeMath: multiplication overflow");
        return c;
    }

    function div(uint256 a, uint256 b) internal pure returns (uint256) {
        return div(a, b, "SafeMath: division by zero");
    }

    function div(uint256 a, uint256 b, string memory errorMessage) internal pure returns (uint256) {
        require(b > 0, errorMessage);
        uint256 c = a / b;
        return c;
    }

    function mod(uint256 a, uint256 b) internal pure returns (uint256) {
        return mod(a, b, "SafeMath: modulo by zero");
    }

    function mod(uint256 a, uint256 b, string memory errorMessage) internal pure returns (uint256) {
        require(b != 0, errorMessage);
        return a % b;
    }
}

abstract contract ERC20 is IERC20 {
    using SafeMath for uint256;

    bytes32 private constant ERC20TOKEN_ERC1820_INTERFACE_ID = keccak256("ERC20Token");

    mapping(address => uint256) internal _balances;
    mapping(address => mapping(address => uint256)) internal _allowances;

    uint256 internal _totalSupply;
    string internal _name;
    string internal _symbol;
    uint8 internal _decimals;

    constructor(string memory name_, string memory symbol_, uint8 decimals_) {
        _name = name_;
        _symbol = symbol_;
        _decimals = decimals_;
    }

    function name() public view returns (string memory) {
        return _name;
    }

    function symbol() public view returns (string memory) {
        return _symbol;
    }

    function decimals() public view returns (uint8) {
        return _decimals;
    }

    function totalSupply() public view override returns (uint256) {
        return _totalSupply;
    }

    function balanceOf(address account) public view virtual override returns (uint256) {
        return _balances[account];
    }

    function transfer(address recipient, uint256 amount) public virtual override returns (bool) {
        _transfer(msg.sender, recipient, amount);
        return true;
    }

    function allowance(address owner, address spender) public view virtual override returns (uint256) {
        return _allowances[owner][spender];
    }

    function approve(address spender, uint256 amount) public virtual override returns (bool) {
        _approve(msg.sender, spender, amount);
        return true;
    }

    function transferFrom(address sender, address recipient, uint256 amount) public virtual override returns (bool) {
        _transfer(sender, recipient, amount);
        _approve(
            sender, msg.sender, _allowances[sender][msg.sender].sub(amount, "ERC20: transfer amount exceeds allowance")
        );
        return true;
    }

    function increaseAllowance(address spender, uint256 addedValue) public virtual returns (bool) {
        _approve(msg.sender, spender, _allowances[msg.sender][spender].add(addedValue));
        return true;
    }

    function decreaseAllowance(address spender, uint256 subtractedValue) public virtual returns (bool) {
        _approve(
            msg.sender,
            spender,
            _allowances[msg.sender][spender].sub(subtractedValue, "ERC20: decreased allowance below zero")
        );
        return true;
    }

    function _transfer(address sender, address recipient, uint256 amount) internal virtual {
        require(sender != address(0), "ERC20: transfer from the zero address");
        require(recipient != address(0), "ERC20: transfer to the zero address");

        _beforeTokenTransfer(sender, recipient, amount);

        _balances[sender] = _balances[sender].sub(amount, "ERC20: transfer amount exceeds balance");
        _balances[recipient] = _balances[recipient].add(amount);
        emit Transfer(sender, recipient, amount);
    }

    function _mint(address account_, uint256 amount_) internal virtual {
        require(account_ != address(0), "ERC20: mint to the zero address");
        _beforeTokenTransfer(address(this), account_, amount_);
        _totalSupply = _totalSupply.add(amount_);
        _balances[account_] = _balances[account_].add(amount_);
        emit Transfer(address(this), account_, amount_);
    }

    function _burn(address account, uint256 amount) internal virtual {
        require(account != address(0), "ERC20: burn from the zero address");

        _beforeTokenTransfer(account, address(0), amount);

        _balances[account] = _balances[account].sub(amount, "ERC20: burn amount exceeds balance");
        _totalSupply = _totalSupply.sub(amount);
        emit Transfer(account, address(0), amount);
    }

    function _approve(address owner, address spender, uint256 amount) internal virtual {
        require(owner != address(0), "ERC20: approve from the zero address");
        require(spender != address(0), "ERC20: approve to the zero address");

        _allowances[owner][spender] = amount;
        emit Approval(owner, spender, amount);
    }

    function _beforeTokenTransfer(address from_, address to_, uint256 amount_) internal virtual {}
}

library Counters {
    using SafeMath for uint256;

    struct Counter {
        uint256 _value;
    }

    function current(Counter storage counter) internal view returns (uint256) {
        return counter._value;
    }

    function increment(Counter storage counter) internal {
        counter._value += 1;
    }

    function decrement(Counter storage counter) internal {
        counter._value = counter._value.sub(1);
    }
}

interface IERC2612Permit {
    function permit(address owner, address spender, uint256 amount, uint256 deadline, uint8 v, bytes32 r, bytes32 s)
        external;

    function nonces(address owner) external view returns (uint256);
}

abstract contract ERC20Permit is ERC20, IERC2612Permit {
    using Counters for Counters.Counter;

    mapping(address => Counters.Counter) private _nonces;

    bytes32 public constant PERMIT_TYPEHASH = 0x6e71edae12b1b97f4d1f60370fef10105fa2faae0126114a169c64845d6126c9;

    bytes32 public DOMAIN_SEPARATOR;

    constructor() {
        uint256 chainID;
        assembly {
            chainID := chainid()
        }

        DOMAIN_SEPARATOR = keccak256(
            abi.encode(
                keccak256("EIP712Domain(string name,string version,uint256 chainId,address verifyingContract)"),
                keccak256(bytes(name())),
                keccak256(bytes("1")),
                chainID,
                address(this)
            )
        );
    }

    function permit(address owner, address spender, uint256 amount, uint256 deadline, uint8 v, bytes32 r, bytes32 s)
        public
        virtual
        override
    {
        require(block.timestamp <= deadline, "Permit: expired deadline");

        bytes32 hashStruct =
            keccak256(abi.encode(PERMIT_TYPEHASH, owner, spender, amount, _nonces[owner].current(), deadline));

        bytes32 _hash = keccak256(abi.encodePacked(uint16(0x1901), DOMAIN_SEPARATOR, hashStruct));

        address signer = ecrecover(_hash, v, r, s);
        require(signer != address(0) && signer == owner, "ERC20Permit: Invalid signature");

        _nonces[owner].increment();
        _approve(owner, spender, amount);
    }

    function nonces(address owner) public view override returns (uint256) {
        return _nonces[owner].current();
    }
}

contract VaultOwned is AccessControl {
    bytes32 public constant MINT = keccak256("MINT");

    constructor() {
        _setupRole(DEFAULT_ADMIN_ROLE, msg.sender);
    }

    modifier onlyVault() {
        require(hasRole(MINT, msg.sender), "VaultOwned: caller is not the Vault");
        _;
    }
}

interface IFeeReceiver {
    function onFeeReceived(uint256 amount) external;
}

contract WebKeyDAO2ERC20Token is ERC20Permit, VaultOwned {
    using SafeMath for uint256;

    constructor() ERC20("WebKey DAO 2.0", "wkeyDAO2", 9) {}

    function mint(address account_, uint256 amount_) external onlyVault {
        _mint(account_, amount_);
    }

    function burn(uint256 amount) public virtual {
        _burn(msg.sender, amount);
    }

    function burnFrom(address account_, uint256 amount_) public virtual {
        _burnFrom(account_, amount_);
    }

    function _burnFrom(address account_, uint256 amount_) internal virtual {
        uint256 decreasedAllowance_ =
            allowance(account_, msg.sender).sub(amount_, "ERC20: burn amount exceeds allowance");

        _approve(account_, msg.sender, decreasedAllowance_);
        _burn(account_, amount_);
    }
}

contract wkeyDAO2 is WebKeyDAO2ERC20Token {
    using SafeMath for uint256;

    address public mainPair;
    address public feeReceiver;
    address public buyFeeReceiver;

    uint256 public constant PRECISION = 100 * 1e3;
    uint256 public feeRatio = 4 * 1e3;  // 4% sell fee
    uint256 public buyFeeRatio;

    bytes32 public constant INTERN_SYSTEM = keccak256("INTERN_SYSTEM");

    event FeeRatioChanged(uint8 ratioType, uint256 ratio);
    event FeeTaken(address indexed payer, address indexed receiver, uint256 left, uint256 fee);
    event FeeReceiverChanged(address indexed oldReceiver, address indexed newReceiver);
    event BuyFeeReceiverChanged(address indexed oldReceiver, address indexed newReceiver);
    event FeeReceiverCallFailed(address indexed feeReceiver, uint256 fee);

    modifier onlyDefaultAdmin() {
        require(hasRole(DEFAULT_ADMIN_ROLE, msg.sender), "Caller is not admin");
        _;
    }

    constructor(address _feeReceiver, address _buyFeeReceiver, uint _buyFeeRatio) WebKeyDAO2ERC20Token() {
        require(_feeReceiver != address(0), "Zero feeReceiver");
        require(_buyFeeReceiver != address(0), "Zero buyFeeReceiver");

        feeReceiver = _feeReceiver;
        buyFeeReceiver = _buyFeeReceiver;
        buyFeeRatio = _buyFeeRatio;

        _setupRole(DEFAULT_ADMIN_ROLE, msg.sender);
        _setupRole(INTERN_SYSTEM, msg.sender);
        _setupRole(INTERN_SYSTEM, _feeReceiver);
    }

    function setMainPair(address pair) external onlyDefaultAdmin {
        mainPair = pair;
    }

    function setFeeReceiver(address _feeReceiver) external onlyDefaultAdmin {
        require(_feeReceiver != address(0), "Zero address");
        emit FeeReceiverChanged(feeReceiver, _feeReceiver);
        feeReceiver = _feeReceiver;
    }

    function setBuyFeeReceiver(address _buyFeeReceiver) external onlyDefaultAdmin {
        require(_buyFeeReceiver != address(0), "Zero address");
        emit BuyFeeReceiverChanged(buyFeeReceiver, _buyFeeReceiver);
        buyFeeReceiver = _buyFeeReceiver;
    }

    function setRatio(uint8 ratioType, uint256 ratio) external onlyDefaultAdmin {
        require(ratio <= PRECISION, "Exceeds precision");
        if (ratioType == 0) {
            buyFeeRatio = ratio;
        } else {
            feeRatio = ratio;
        }
        emit FeeRatioChanged(ratioType, ratio);
    }

    function _transfer(address sender, address recipient, uint256 amount) internal virtual override {
        require(sender != address(0), "ERC20: transfer from the zero address");
        require(recipient != address(0), "ERC20: transfer to the zero address");

        _beforeTokenTransfer(sender, recipient, amount);

        _balances[sender] = _balances[sender].sub(amount, "ERC20: transfer amount exceeds balance");

        if (_isTradeAndNotInSystem(sender, recipient)) {
            // buy
            if (sender == mainPair) {
                uint buyFee = amount.mul(buyFeeRatio).div(PRECISION);

                if (buyFee > 0) {
                    amount = amount - buyFee;
                    _balances[buyFeeReceiver] += buyFee;
                    emit Transfer(sender, buyFeeReceiver, buyFee);
                }
                require(amount > 0, "Buy disabled");
            }
            else if (recipient == mainPair) {
                uint256 fee = amount.mul(feeRatio).div(PRECISION);
                if (fee > 0) {
                    amount = amount - fee;
                    _balances[feeReceiver] += fee;
                    emit Transfer(sender, feeReceiver, fee);
                    emit FeeTaken(sender, feeReceiver, amount, fee);
                    try IFeeReceiver(feeReceiver).onFeeReceived(fee) {
                    } catch {
                        emit FeeReceiverCallFailed(feeReceiver, fee);
                    }
                }
            }
        }

        _balances[recipient] = _balances[recipient].add(amount);

        emit Transfer(sender, recipient, amount);
    }

    function _isTradeAndNotInSystem(address _from, address _to) internal view returns (bool) {
        return (_from == mainPair && !hasRole(INTERN_SYSTEM, _to)) || (_to == mainPair && !hasRole(INTERN_SYSTEM, _from));
    }
}

